/**
 * The Microsoft Entra setup checklist (Admin › Configuration › Microsoft apps).
 *
 * Everything the platform needs from Entra is printed here with this deployment's
 * own values, so an Entra administrator copies it and nothing is left to guess: the
 * ONE Web redirect URI (the same for web, desktop and mobile), the delegated
 * permissions each credential type asks for, the admin consent URL, and the
 * secret-expiry warning. The facts are generated by the server
 * (`internal/microsoftapps/checklist.go`); this file only lays them out.
 */
import Alert from '@mui/material/Alert';
import Box from '@mui/material/Box';
import Chip from '@mui/material/Chip';
import Typography from '@mui/material/Typography';

import type {
  MicrosoftAppChecklist,
  MicrosoftAppDeploymentChecklist,
  MicrosoftAppResource,
} from '@/shared/api/generated/model';
import { t } from '@/shared/i18n';

import { AdminScimCopyField } from './AdminScimCopyField';

function RedirectStep({ redirectUri, issue }: { readonly redirectUri: string; readonly issue: string | undefined }) {
  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
      <Typography variant="bodyMedium">
        {t(
          'pages.admin.microsoftApps.checklist.redirect',
          'Authentication, add a platform, Web, and enter this redirect URI. It is the only one needed, for web, desktop and mobile; do not register a custom scheme or a loopback address.',
        )}
      </Typography>
      <AdminScimCopyField
        label={t('pages.admin.microsoftApps.checklist.redirectLabel', 'Redirect URI')}
        value={redirectUri}
        testId="microsoft-app-redirect-uri"
      />
      {issue === undefined || issue === '' ? null : (
        <Alert severity="warning" data-testid="microsoft-app-redirect-issue">
          {t(
            'pages.admin.microsoftApps.checklist.httpsRequired',
            'This deployment is reached over plain http, and Microsoft accepts http only for localhost. Set DEPLOYMENT_URL to the public https address.',
          )}
        </Alert>
      )}
    </Box>
  );
}

function PermissionList({ resources }: { readonly resources: readonly MicrosoftAppResource[] }) {
  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }} data-testid="microsoft-app-permissions">
      {resources.map((resource) => (
        <Box key={resource.api}>
          <Typography variant="bodySmall" color="text.secondary">
            {resource.api}
          </Typography>
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: '0.25rem' }}>
            {resource.permissions.map((permission) => (
              <Chip
                key={permission.name}
                size="small"
                variant="outlined"
                label={
                  permission.admin_consent
                    ? t('pages.admin.microsoftApps.checklist.needsConsent', '{{name}} (admin consent)', {
                        name: permission.name,
                      })
                    : permission.name
                }
              />
            ))}
          </Box>
        </Box>
      ))}
    </Box>
  );
}

function ExpiryNotice({ state, days }: { readonly state: string; readonly days: number }) {
  if (state === 'expired') {
    return (
      <Alert severity="error" data-testid="microsoft-app-expiry">
        {t('pages.admin.microsoftApps.checklist.expired', 'The client secret has expired. Create a new one in Entra and enter it here.')}
      </Alert>
    );
  }
  if (state !== 'expiring') return null;
  return (
    <Alert severity="warning" data-testid="microsoft-app-expiry">
      {t(
        'pages.admin.microsoftApps.checklist.expiring',
        'The client secret expires in {{count}} days. Create a new one in Entra and enter it here before then.',
        { count: Math.max(days, 0) },
      )}
    </Alert>
  );
}

/** The checklist of one app: its redirect URI, permissions, consent URL and expiry. */
export function AppChecklist({ checklist }: { readonly checklist: MicrosoftAppChecklist }) {
  return (
    <Box component="ol" sx={{ m: 0, pl: '1.25rem', display: 'flex', flexDirection: 'column', gap: '0.75rem' }} data-testid="microsoft-app-checklist">
      <li>
        <Typography variant="bodyMedium">
          {checklist.account_types === 'multi'
            ? t(
                'pages.admin.microsoftApps.checklist.registerMulti',
                'App registrations, New registration. Supported account types: accounts in any organizational directory (multitenant).',
              )
            : t(
                'pages.admin.microsoftApps.checklist.registerSingle',
                'App registrations, New registration. Supported account types: accounts in this organizational directory only (single tenant).',
              )}
        </Typography>
      </li>
      <li>
        <RedirectStep redirectUri={checklist.redirect_uri} issue={checklist.redirect_issue} />
      </li>
      <li>
        <Typography variant="bodyMedium">
          {t(
            'pages.admin.microsoftApps.checklist.permissions',
            'API permissions, add the delegated permissions below (Delegated, not Application).',
          )}
        </Typography>
        <PermissionList resources={checklist.permissions} />
      </li>
      <li>
        <Typography variant="bodyMedium">
          {checklist.needs_admin_consent
            ? t(
                'pages.admin.microsoftApps.checklist.consentNeeded',
                'Grant admin consent: some permissions need it. An Entra administrator opens this address and approves.',
              )
            : t(
                'pages.admin.microsoftApps.checklist.consentOptional',
                'Optionally grant admin consent for the whole organization, so people are not asked one by one. An Entra administrator opens this address and approves.',
              )}
        </Typography>
        <AdminScimCopyField
          label={t('pages.admin.microsoftApps.checklist.consentLabel', 'Admin consent URL')}
          value={checklist.admin_consent_url}
          testId="microsoft-app-consent-url"
        />
        {checklist.account_types === 'multi' ? (
          <Typography variant="bodySmall" color="text.secondary">
            {t(
              'pages.admin.microsoftApps.checklist.consentTenant',
              'Replace {tenant-id} with the tenant ID of each organization that signs in.',
            )}
          </Typography>
        ) : null}
      </li>
      <li>
        <Typography variant="bodyMedium">
          {t(
            'pages.admin.microsoftApps.checklist.secret',
            'Certificates and secrets, New client secret. Paste its value here, and enter its expiry so this page can warn you 30 days before.',
          )}
        </Typography>
        <ExpiryNotice state={checklist.secret_expiry} days={checklist.secret_days_left} />
      </li>
    </Box>
  );
}

/**
 * The setup that does not depend on an app yet: what to do in Entra before the first
 * client id exists. Shown above the list, so it is there while the registry is empty.
 */
export function DeploymentChecklist({ checklist }: { readonly checklist: MicrosoftAppDeploymentChecklist }) {
  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }} data-testid="microsoft-deployment-checklist">
      <Typography variant="bodyMedium">
        {t(
          'pages.admin.microsoftApps.deployment.intro',
          'Register one app in Microsoft Entra for each set of permissions you want to offer. Everything Entra needs from this deployment is below.',
        )}
      </Typography>
      <RedirectStep redirectUri={checklist.redirect_uri} issue={checklist.redirect_issue} />
      <Typography variant="bodyMedium">
        {t('pages.admin.microsoftApps.deployment.permissions', 'Delegated permissions each credential type can ask for:')}
      </Typography>
      {checklist.types.map((info) => (
        <Box key={info.type} data-testid={`microsoft-type-${info.type}`}>
          <Typography variant="bodySmall" color="text.secondary">
            {t('pages.admin.microsoftApps.deployment.type', '{{type}} ({{api}})', { type: info.type, api: info.api })}
          </Typography>
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: '0.25rem' }}>
            {(info.offered.length > 0 ? info.offered.map((permission) => permission.name) : info.default).map((name) => (
              <Chip
                key={name}
                size="small"
                variant={info.default.includes(name) ? 'filled' : 'outlined'}
                label={name}
              />
            ))}
          </Box>
        </Box>
      ))}
      <Typography variant="bodySmall" color="text.secondary">
        {t(
          'pages.admin.microsoftApps.deployment.note',
          'Filled chips are the defaults. Microsoft Graph and SharePoint take any Graph permission name. ChannelMessage.Read.All needs admin consent.',
        )}
      </Typography>
    </Box>
  );
}
